#!/bin/sh
# Klart request handler "__ID__", generated by /add-request-handler.
# Runs a command for each Klart "request file" automation it knows, then deletes the request files.
# Request files: requests/<time>-<name>.json, schema klart.request/v1 (see LLMS.txt in the data folder).
set -u

KLART_DIR="__KLART_DIR__" # the sync folder, or a Git clone of the data repository
SYNC="__SYNC__"           # folder | git
BRANCH="__BRANCH__"       # git only
LOG="__LOG_FILE__"
# When each job last succeeded, for the spam guard. ponytail: lost between GitHub Actions runs, so no guard there.
STATE="$HOME/.klart/requests/__ID__/last-ok"

# Schedulers start with a bare PATH, and a login shell doesn't read ~/.zshrc or ~/.bashrc,
# so the directories of the commands below are spelled out.
export PATH="__PATH__:$PATH"

# One arm per automation name, exactly as named in Klart's Settings. Runs in $KLART_DIR.
# Return 0 on success. Names not listed here are left alone for another handler (199).
handle() {
  case "$1" in
__HANDLERS__
    *) return 199 ;;
  esac
}

log() {
  printf '%s %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$*" >>"$LOG"
}

LOCK="/tmp/klart-requests-__ID__.lock"
if ! mkdir "$LOCK" 2>/dev/null; then
  pid=$(cat "$LOCK/pid" 2>/dev/null || true)
  if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
    exit 0
  fi
  rm -rf "$LOCK"
  mkdir "$LOCK" || exit 0
fi
echo $$ >"$LOCK/pid"
trap 'rm -rf "$LOCK"' EXIT INT TERM

mkdir -p "$(dirname "$LOG")" "$(dirname "$STATE")"
cd "$KLART_DIR" || {
  log "error: can't open $KLART_DIR"
  exit 1
}

if [ "$SYNC" = git ]; then
  git fetch --quiet origin "$BRANCH" && git merge --ff-only --quiet "origin/$BRANCH" || {
    log "error: can't fast-forward $KLART_DIR to origin/$BRANCH; is the clone in use or edited by hand?"
    exit 1
  }
fi

ls requests/*.json >/dev/null 2>&1 || exit 0

# The automation name of each request, one per line, oldest first (file names sort by time).
names=$(for file in requests/*.json; do
  sed -n 's/^ *"automation": *"\(.*\)",\{0,1\}$/\1/p' "$file"
done | awk '!seen[$0]++')

FAILED="$LOCK/failed"
echo "$names" | while IFS= read -r name; do
  [ -n "$name" ] || continue
  # Every pending request for this name, so pressing Run twice runs the job once.
  files=$(grep -F -l "\"automation\": \"$name\"" requests/*.json)
  # Spam guard: a request made before this job last finished (Run pressed while it ran) is dropped.
  done_at=$(awk -F'\t' -v n="$name" '$2 == n { t = $1 } END { print t }' "$STATE" 2>/dev/null)
  if [ -n "$done_at" ]; then
    stale=$(echo "$files" | while IFS= read -r file; do
      at=$(sed -n 's/^ *"requestedAt": *"\(.*\)",\{0,1\}$/\1/p' "$file")
      [ -n "$at" ] && awk -v a="$at" -v b="$done_at" 'BEGIN { exit !(a < b) }' && echo "$file"
    done)
    if [ -n "$stale" ]; then
      echo "$stale" | while IFS= read -r file; do rm -f "$file"; done
      log "skipped: $name: $(echo "$stale" | wc -l | tr -d ' ') request(s) made before its last run finished"
      files=$(echo "$files" | grep -vxF "$stale")
      [ -n "$files" ] || continue
    fi
  fi
  first=$(echo "$files" | head -n 1)
  export KLART_DIR KLART_AUTOMATION="$name" KLART_REQUEST="$KLART_DIR/$first"
  export KLART_DEVICE="$(sed -n 's/^ *"device": *"\(.*\)",\{0,1\}$/\1/p' "$first")"
  output=$(handle "$name" 2>&1 </dev/null)
  code=$?
  if [ "$code" = 199 ]; then
    continue
  fi
  if [ "$code" = 0 ]; then
    log "ok: $name"
    printf '%s\t%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$name" >>"$STATE"
    echo "$files" | while IFS= read -r file; do rm -f "$file"; done
  else
    log "failed ($code): $name: $(echo "$output" | tail -n 1)"
    touch "$FAILED"
    mkdir -p requests/failed
    echo "$files" | while IFS= read -r file; do mv "$file" requests/failed/; done
  fi
done

if [ "$SYNC" = git ] && [ -n "$(git status --porcelain)" ]; then
  git add -A
  git -c user.name="${GIT_AUTHOR_NAME:-Klart requests}" -c user.email="${GIT_AUTHOR_EMAIL:-klart@localhost}" \
    commit --quiet -m "klart: handled requests" || exit 1
  for attempt in 1 2 3; do
    if git push --quiet origin "HEAD:$BRANCH" 2>/dev/null; then
      break
    fi
    git pull --rebase --quiet origin "$BRANCH" || {
      git rebase --abort 2>/dev/null
      log "error: rebase onto origin/$BRANCH failed"
      exit 1
    }
    if [ "$attempt" = 3 ]; then
      log "error: push to origin/$BRANCH failed 3 times"
      exit 1
    fi
  done
fi

# A failed job exits non-zero, so a GitHub Actions run shows it.
[ ! -e "$FAILED" ]
